package main

import (
	"strings"
	"testing"
)

func TestGenerateGeometryBoundaries(t *testing.T) {
	css := string(generate())
	for _, want := range []string{
		"Code generated by go run ./scripts/gen-geometry; DO NOT EDIT.",
		".swipe-x--200 { transform: translateX(-800px); }",
		".swipe-x-200 { transform: translateX(800px); }",
		".ctx-left-255 { left: 2040px; }",
		".ctx-top-255 { top: 2040px; }",
		".cal-top-1439 { top: 99.930556%; }",
		".cal-height-30 { height: 2.083333%; }",
		".cal-height-1440 { height: 100.000000%; }",
	} {
		if !strings.Contains(css, want) {
			t.Errorf("generated CSS does not contain %q", want)
		}
	}
}

func TestGenerateGeometryClassCounts(t *testing.T) {
	css := string(generate())
	checks := map[string]int{
		"\n.swipe-x-":    401,
		"\n.ctx-left-":   256,
		"\n.ctx-top-":    256,
		"\n.cal-top-":    1440,
		"\n.cal-height-": 1411,
	}
	for prefix, want := range checks {
		if got := strings.Count(css, prefix); got != want {
			t.Errorf("%s classes = %d, want %d", prefix, got, want)
		}
	}
}
